{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "N8N JARVIS Webhook Response",
  "description": "Simple schema for n8n webhook responses to JARVIS persona queries",
  "type": "object",
  "properties": {
    "response": {
      "type": "string",
      "description": "The text response from JARVIS"
    }
  },
  "required": ["response"],
  "examples": [
    {
      "response": "My pleasure, Sir"
    },
    {
      "response": "Right away, Sir. I'll handle that for you."
    },
    {
      "response": "Of course, Sir. Consider it done."
    }
  ]
}
